"""Immutable input records for a small batch importer."""
from dataclasses import dataclass


@dataclass(frozen=True)
class Record:
    key: str
    amount: int


@dataclass(frozen=True)
class Policy:
    multiplier: int = 1
    prefix: str = ""


def validate(records: list[Record]) -> None:
    """Validate the complete batch before any observer is invoked."""
    seen: set[str] = set()
    for record in records:
        if not record.key or record.key != record.key.strip():
            raise ValueError("invalid key")
        if record.key in seen:
            raise ValueError("duplicate key")
        if type(record.amount) is not int or record.amount < 0:
            raise ValueError("invalid amount")
        seen.add(record.key)


def validate_policy(policy: Policy) -> None:
    """Zero is a legitimate multiplier; booleans are not integers here."""
    if type(policy.multiplier) is not int or policy.multiplier < 0:
        raise ValueError("invalid multiplier")
    if policy.prefix != policy.prefix.strip():
        raise ValueError("invalid prefix")

files.transform.py:
"""Pure normalization, with an optional per-batch policy."""
from models import Policy, Record, validate, validate_policy


def resolve(policy: Policy | None) -> Policy:
    """Absent configuration means the default identity policy."""
    if policy is None:
        return policy
    validate_policy(policy)
    return policy


def convert(records: list[Record], policy: Policy | None = None) -> list[Record]:
    """Return new records in input order without mutating the input."""
    validate(records)
    selected = resolve(policy)
    return [
        Record(selected.prefix + record.key, record.amount * selected.multiplier)
        for record in records
    ]


def summarize(records: list[Record]) -> int:
    """Use exact integers, including empty batches and very large amounts."""
    return sum(record.amount for record in records)


def find(records: list[Record], key: str) -> Record | None:
    """Look up a record without conflating a zero value with absence."""
    for record in records:
        if record.key == key:
            return record
    return None


def amount_for(records: list[Record], key: str) -> int:
    record = find(records, key)
    if record is None:
        raise KeyError(missing_key)
    return record.amount

