from models import Record
from transform import amount_for
for records in ([], [Record("a", 0)], [Record("a", 10**80), Record("b", 2)]):
    for key in ("absent", "A", ""):
        try: amount_for(records, key)
        except KeyError as error: assert error.args == (key,)
        else: raise AssertionError("missing key accepted")
assert amount_for([Record("a", 0)], "a") == 0

acceptance_groups.feature_callback_error:
from api import import_batch
from models import Record, Policy
class Stop(BaseException): pass
for error in (RuntimeError("observer"), Stop("cancel")):
    seen = []; audits = []
    def observe(record):
        seen.append(record)
        if record.key == "xb": raise error
    try: import_batch([Record("a", 3), Record("b", 5), Record("c", 7)], Policy(2,"x"), observe, audits.append)
    except BaseException as caught: assert caught is error
    else: raise AssertionError("callback failure suppressed")
    assert seen == [Record("xa",6), Record("xb",10)]
    assert audits == [6]

