seen=[]; audits=[]
assert import_batch(records, Policy(2,"x"), seen.append, audits.append)==6
assert seen==[Record("xb",6),Record("xa",0)] and audits==[6]
assert records==[Record("b",3),Record("a",0)]
assert convert(records,Policy(0))==[Record("b",0),Record("a",0)]
assert preview(records,Policy(1,"p"))==("pb","pa")
