"""Immutable input records for a small batch importer."""
from dataclasses import dataclass


@dataclass(frozen=True)
class Record:
    key: str
    units: int


@dataclass(frozen=True)
class Policy:
    factor: int = 1
    namespace: str = ""


def validate(records: list[Record]) -> None:
    """Validate the complete batch before any observer is invoked."""
    seen: set[str] = set()
    for record in records:
        if not record.key or record.key != record.key.strip():
            raise ValueError("invalid key")
        if record.key in seen:
            raise ValueError("duplicate key")
        if type(record.units) is not int or record.units < 0:
            raise ValueError("invalid units")
        seen.add(record.key)


def validate_policy(policy: Policy) -> None:
    """Zero is a legitimate factor; booleans are not integers here."""
    if type(policy.factor) is not int or policy.factor < 0:
        raise ValueError("invalid factor")
    if policy.namespace != policy.namespace.strip():
        raise ValueError("invalid namespace")

